export function positionFix(position){const p={lat:position?.coords?.latitude,lng:position?.coords?.longitude,accuracy:position?.coords?.accuracy,t:position?.timestamp};if(!Object.values(p).every(Number.isFinite)||Math.abs(p.lat)>90||Math.abs(p.lng)>180||p.accuracy<0)throw new Error('O aparelho retornou uma posição inválida. Tente novamente.');return p;}
export function locationError(error){if(error?.code===1)return 'Sem permissão de localização. Libere o acesso nas configurações do navegador e tente novamente. Se estiver dentro do ChatGPT, abra o link diretamente no Safari ou Chrome.';if(error?.code===2)return 'O aparelho não conseguiu obter a localização. Confira o GPS, a conexão e tente em local aberto.';if(error?.code===3)return 'O GPS demorou para responder. Tente novamente, de preferência em local aberto.';return error?.message||'Não foi possível obter a localização.';}
export function locate(geo=globalThis.navigator?.geolocation){if(!geo)return Promise.reject(new Error('Localização indisponível neste navegador. Abra o Borali pelo Safari ou Chrome.'));return new Promise((resolve,reject)=>geo.getCurrentPosition(p=>{try{resolve(positionFix(p));}catch(e){reject(e);}},reject,{enableHighAccuracy:true,maximumAge:0,timeout:15000}));}
